from functools import lru_cache
@lru_cache(maxsize=None)
def square(x: int) -> int:
    return x*x
print(square(3), square(3))

recursive_forward.source:
def empty(n):
    out = []
    return out
def a(n):
    if n <= 0:
        return empty(n)
    r = b(n - 1)
    r.append(n)
    return r
def b(n):
    return a(n)
print(a(3))

